export const colourLessons=rows.map((pair,id)=>({id,lecture:id>0&&id<13?id:null,bridge:bridges[id],...Object.fromEntries(pair.map((r,i)=>{const pt=i===1,s=colourSources[id-1];return [pt?'pt':'en',{title:r[0],goal:r[1],key:r[2],context:r[3],example:r[4],explanation:r[5],activity:r[6],takeaway:r[7],terms:r[8],reading:id===0?(pt?'Prefácio e sumários; depois, Palestras 1–3.':'Foreword and synopses; then Lectures 1–3.'):id===13?(pt?'Retome as Palestras 1–12, sobretudo as duas usadas no portfólio.':'Revisit Lectures 1–12, especially the two used in your portfolio.'):`${pt?'Palestra':'Lecture'} ${id} · ${s.date} · GA ${s.ga} · ${pt?'páginas da captura':'capture pages'} ${s.pages}.`,checks:[[r[9],r[10]],[pt?'Como o exemplo ajuda a compreender a leitura?':'How does the example help you understand the reading?',r[5]],[pt?'O que você deve mostrar na atividade?':'What should your activity demonstrate?',r[6]]]}]}))}));
const practiceAnswers=[
 ['“Blue centre on white” records an arrangement; “I find it quiet” reports experience; “it expresses soul” interprets it. The three sentences may concern one study without making the same claim.','“Centro azul sobre branco” registra uma disposição; “acho tranquilo” relata uma experiência; “expressa a alma” interpreta. As três frases podem tratar de um estudo sem fazer a mesma afirmação.'],
 ['A useful entry names the changed central colour and a specific effect on the green field. It then explains that the painted image is not itself a living plant. Agreement with every proposed feeling is unnecessary.','Um registro útil identifica a cor central alterada e um efeito específico sobre o campo verde. Depois explica que a imagem pintada não é uma planta viva. Não é necessário concordar com todo sentimento proposto.'],
 ['Compare the original centre-to-edge yellow transition with the reversed one. Describe a difference in emphasis or movement, or state that none was clear. Do not label one study morally better.','Compare a transição amarela original, do centro à borda, com a invertida. Descreva uma diferença de ênfase ou movimento, ou registre que nenhuma foi clara. Não classifique um estudo como moralmente superior.'],
 ['“I planned the leaf outline first, but discovered a curved edge where the washes met” identifies two different processes. Explain which served your aim rather than declaring that one medium always wins.','“Planejei primeiro o contorno da folha, mas descobri uma borda curva no encontro das aguadas” identifica processos diferentes. Explique qual serviu à sua intenção, sem declarar que um material sempre vence.'],
 ['State what stayed constant and compare the direction of attention in the two versions. A second observer’s different response is useful information, not a failed exercise.','Declare o que permaneceu constante e compare a direção da atenção nas versões. Uma resposta diferente de outra pessoa é informação útil, não fracasso do exercício.'],
 ['“This blue beside grey feels lonely to me” locates the response in a particular relation and person. It does not assign loneliness to every blue object or moral worth to its owner.','“Este azul junto ao cinza me parece solitário” situa a resposta numa relação e pessoa específicas. Não atribui solidão a todo objeto azul nem valor moral a seu dono.'],
 ['The completed decision illustrates something formed; the intended revision illustrates something still to become. Explicitly limit the analogy: neither entry is a measurement of spiritual light or darkness.','A decisão concluída ilustra algo formado; a revisão pretendida, algo em formação. Limite explicitamente a analogia: nenhum registro mede luz ou escuridão espiritual.'],
 ['Moving a brush and mixing paint describe a process; wanting to welcome visitors gives a reason. Add Steiner’s future-world interpretation as a separately attributed claim.','Mover um pincel e misturar tinta descrevem um processo; querer acolher visitantes apresenta uma razão. Acrescente a interpretação de mundo futuro de Steiner como afirmação atribuída separadamente.'],
 ['A useful record identifies the same sheet, both backgrounds and the lighting. If only brightness changed, say so; do not invent a blue or red effect to fit the reading.','Um registro útil identifica a mesma folha, os dois fundos e a iluminação. Se apenas a claridade mudou, diga isso; não invente um efeito azul ou vermelho para concordar com a leitura.'],
 ['Describe the colour-only comparison first, then the version with overlap. This prevents attributing a depth change caused by overlap entirely to colour.','Descreva primeiro a comparação apenas cromática e depois a versão com sobreposição. Isso evita atribuir inteiramente à cor uma mudança de profundidade causada pela sobreposição.'],
 ['Name a specific middle-region transition, such as a dark red becoming lighter toward the top, and explain its role. Merely calling the top “heaven” does not explain the composition.','Nomeie uma transição específica na região intermediária, como um vermelho escuro que clareia para cima, e explique seu papel. Apenas chamar o alto de “céu” não explica a composição.'],
 ['Keep the dark patch’s size fixed while moving it. Support your judgment with its new relation to the edge or centre, not with a claim that its physical mass changed.','Mantenha o tamanho da área escura ao movê-la. Apoie seu juízo na nova relação com a borda ou o centro, não na afirmação de que sua massa física mudou.'],
 ['A complete map preserves the order warmth, light, colour and life/form. One question can clarify “shadow”; another can ask what supports the account’s historical or spiritual claims.','Um mapa completo preserva a ordem calor, luz, cor e vida/forma. Uma pergunta pode esclarecer “sombra”; outra pode perguntar o que sustenta as afirmações históricas ou espirituais da narrativa.'],
 ['A strong submission shows the initial and revised arrangement, names two lecture ideas and explains a concrete change. It distinguishes the felt result from a wider spiritual interpretation.','Uma boa entrega mostra a disposição inicial e a revisada, nomeia duas ideias das palestras e explica uma mudança concreta. Distingue o resultado sentido de uma interpretação espiritual mais ampla.']
];
for(const l of colourLessons)for(const [i,lang] of ['en','pt'].entries())l[lang].checks[2]=[lang==='pt'?'Como seria uma resposta bem fundamentada à atividade?':'What would a well-supported response to the activity include?',practiceAnswers[l.id][i]];
